const item = items[0].json;

// 1. 유저의 질문 텍스트 추출 및 봇 멘션 태그(<@U...>) 제거
let cleanedPrompt = item.text || "";
cleanedPrompt = cleanedPrompt.replace(/<@U[A-Z0-9]+>/g, "").trim();

// 2. 답장을 달기 위한 쓰레드 TS 추출 (쓰레드가 없다면 부모 메시지의 TS 활용)
const threadTs = item.thread_ts || item.ts;

return [{
  json: {
    user_prompt: cleanedPrompt,
    channel_id: item.channel,
    thread_ts: threadTs
  }
}];
